INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 12, 'theory', 'Quiz: Containers and Virtual Machines');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 0, 'What is the main difference between a container and a virtual machine?', '["A container has its own kernel", "Containers use the host''s shared kernel, while a machine brings its own and is fenced off by the hypervisor", "Virtual machines cannot limit resources", "Containers need a hypervisor"]', 1, 'Both the speed of containers and the sharpness of the security question follow from the shared kernel.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 1, 'What do namespaces do?', '["Show a process its own version of resources: numbering, files, network, hostname, users", "Limit memory", "Encrypt the disk", "Schedule the CPU"]', 0, 'A container is a set of such namespaces for a group of processes, plus cgroups limits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 2, 'What happens when you write to a file in a lower image layer in overlayfs?', '["The lower layer is changed", "The write is discarded", "The file is copied to the top layer and changed there", "The layers are merged"]', 2, 'This is copy-on-write; deleting a file puts a whiteout marker in the top layer that hides it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 3, 'Why are containers usually not enough as the only protection for untrusted code?', '["They are too slow", "They don''t support networking", "They need root rights", "The boundary runs along the shared kernel''s system calls, and a bug in any one of them allows an escape"]', 3, 'Other people''s tenants need a stronger boundary: a virtual machine, Kata, or gVisor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 4, 'How does Kata Containers differ from gVisor?', '["They are the same", "Kata runs a container inside a lightweight virtual machine (a hardware boundary), while gVisor replaces the host kernel with its own kernel in user space", "gVisor is a hypervisor", "Kata is always faster"]', 1, 'Kata pays in memory and start time for a hardware boundary, gVisor pays in system call speed and compatibility.');
